<script setup>
import { computed, ref } from 'vue';
import { ElDialog } from 'element-plus';
import 'element-plus/es/components/dialog/style/css';
import { useRouter } from 'vue-router';
import { api, dateLabel, runLabels } from '../api';
import { workspace, loadWorkspace, selectBoard } from '../workspace';
import EmptyState from '../components/EmptyState.vue';
import StatusBadge from '../components/StatusBadge.vue';
import AppIcon from '../components/AppIcon.vue';
const router = useRouter();
const creating = ref(false), name = ref(''), busy = ref(false), error = ref(''), query = ref('');
const example = computed(() => workspace.boards.find(board => board.name === '0918全量'));
const filteredBoards = computed(() => workspace.boards.filter(board => board.name.toLowerCase().includes(query.value.trim().toLowerCase())));
const reportCount = computed(() => workspace.boards.filter(board => board.latest_report).length);
const runningCount = computed(() => workspace.boards.filter(board => board.active_run).length);
function open(board, path='/materials') { selectBoard(board.id); router.push({path,query:{board:board.id}}); }
async function create() {
  if (!name.value.trim()) { error.value='请填写项目名称。'; return; }
  busy.value=true; error.value='';
  try { const value=await api.createBoard(name.value.trim()); await loadWorkspace(); creating.value=false; name.value=''; open(value.board || value); }
  catch(e) { error.value=e.message; } finally { busy.value=false; }
}
const reportId = value => typeof value === 'string' ? value : value?.id || value?.run_id;
function openReport(board) { selectBoard(board.id); router.push({path:'/reports',query:{board:board.id,...(reportId(board.latest_report)?{run:reportId(board.latest_report)}:{})}}); }
</script>
<template>
  <section class="projects-page">
    <div class="page-heading"><div><div class="eyebrow">PROJECT OVERVIEW</div><h1>项目总览</h1><p>从设计材料到评审结论，在同一个工作区完成核对。</p></div><button class="button primary" @click="creating=true"><AppIcon name="plus" :size="17" />新建项目</button></div>
    <div class="project-overview" aria-label="项目概况">
      <div class="overview-metric"><span class="metric-icon"><AppIcon name="folder" :size="21" /></span><div><span>全部项目</span><strong>{{ workspace.boards.length }}<small>个板卡项目</small></strong></div></div>
      <div class="overview-metric"><span class="metric-icon reports"><AppIcon name="layers" :size="21" /></span><div><span>已生成报告</span><strong>{{ reportCount }}<small>个项目可复核</small></strong></div></div>
      <div class="overview-metric"><span class="metric-icon running"><AppIcon name="play" :size="21" /></span><div><span>正在执行</span><strong>{{ runningCount }}<small>{{ runningCount?'后台任务执行中':'暂无运行中的任务' }}</small></strong></div></div>
    </div>
    <div class="project-list-toolbar"><div><h2>板卡项目 <span class="count-label">{{ filteredBoards.length }}</span></h2><p>选择项目，继续材料准备或查看最新评审。</p></div><div class="actions"><div class="project-search"><AppIcon name="search" :size="17" /><label class="sr-only" for="project-search">搜索项目名称</label><input id="project-search" v-model="query" placeholder="搜索项目名称" /></div><button class="button icon-button" :disabled="workspace.loading" @click="loadWorkspace" aria-label="刷新项目列表" title="刷新项目列表"><AppIcon name="refresh" :size="17" /></button></div></div>
    <div v-if="workspace.loading&&!workspace.initialized" class="loading-state" aria-live="polite">正在加载项目</div>
    <EmptyState v-else-if="!workspace.boards.length&&!workspace.error" title="创建第一个评审项目" description="为板卡命名，再导入原理图、BOM 和网表。每次运行都将保留独立的评审记录。"><button class="button primary" @click="creating=true"><AppIcon name="plus" />新建项目</button></EmptyState>
    <EmptyState v-else-if="!filteredBoards.length&&!workspace.error" title="没有找到匹配的项目" description="试试其他项目名称，或清空搜索查看全部项目。"><button class="button" @click="query=''">清空搜索</button></EmptyState>
    <div v-else class="project-grid"><article v-for="board in filteredBoards" :key="board.id" class="project-card" :class="{'current-project':String(board.id)===workspace.boardId}">
      <div class="project-card-top"><span class="project-symbol"><AppIcon name="circuit" :size="25" /></span><StatusBadge v-if="board.active_run" tone="info">{{ runLabels[board.active_run.status] || '有运行任务' }}</StatusBadge><StatusBadge v-else :tone="board.latest_report?'success':'neutral'">{{ board.latest_report?'报告可复核':'待评审' }}</StatusBadge></div>
      <div class="project-title"><h3>{{ board.name }}</h3><span v-if="String(board.id)===workspace.boardId" class="current-project-label">当前项目</span></div>
      <p class="project-description">{{ board.active_run?'任务正在后台执行，可继续查看运行进度。':board.latest_report?'评审记录已保存，可进入工作台核对结论与证据。':'导入设计材料，准备一次有据可查的评审。' }}</p>
      <div class="project-card-meta"><span><AppIcon name="file" :size="14" />材料版本</span><span class="mono">{{ board.material_version ? String(board.material_version).slice(0,10) : '待建立' }}</span></div>
      <div class="project-card-meta"><span><AppIcon name="clock" :size="14" />{{ board.latest_report?.created_at?'最近报告':'最近更新' }}</span><span>{{ dateLabel(board.latest_report?.created_at||board.updated_at||board.created_at) }}</span></div>
      <div class="project-card-actions"><button v-if="board.latest_report" class="button primary" @click="openReport(board)">进入评审<AppIcon name="arrow-right" :size="16" /></button><button v-else class="button primary" @click="open(board)">准备材料<AppIcon name="arrow-right" :size="16" /></button><button class="button ghost" @click="open(board,board.active_run?'/runs':board.latest_report?'/materials':'/runs')">{{ board.active_run?'查看运行':board.latest_report?'查看材料':'配置检查' }}</button></div>
      <details class="project-file-details"><summary>项目信息<AppIcon name="chevron-down" :size="13" /></summary><dl><dt>存储位置</dt><dd>{{ board.path || '工作台项目' }}</dd><dt>材料版本</dt><dd class="mono">{{ board.material_version||'尚未建立' }}</dd></dl></details>
    </article></div>
    <div class="workflow-guide" aria-label="评审流程"><div class="workflow-guide-heading"><AppIcon name="circuit" :size="19" /><strong>一个项目，三步完成核对</strong></div><div class="workflow-strip"><div><span>01</span><strong>准备材料</strong><small>核对图纸、网表与 BOM</small></div><AppIcon name="chevron-right" :size="16" /><div><span>02</span><strong>执行检查</strong><small>明确范围，追踪后台进度</small></div><AppIcon name="chevron-right" :size="16" /><div><span>03</span><strong>复核结论</strong><small>回到证据，记录人工意见</small></div></div><button v-if="example" class="button ghost small" @click="open(example)">查看「0918全量」材料<AppIcon name="arrow-right" :size="14" /></button></div>
    <el-dialog v-model="creating" title="新建评审项目" width="min(480px, calc(100vw - 32px))" :close-on-click-modal="!busy" :close-on-press-escape="!busy"><form @submit.prevent="create"><div class="field"><label for="project-name">项目名称</label><input id="project-name" v-model="name" maxlength="100" placeholder="例如：电源控制板 R2" autofocus :disabled="busy" required aria-describedby="project-name-help" /><span id="project-name-help" class="help">为板卡建立独立工作区，后续导入材料并保留评审批次。</span></div><div v-if="error" class="notice error" role="alert">{{ error }}</div><div class="actions"><button class="button primary" :disabled="busy">{{ busy?'正在创建…':'创建项目' }}</button><button class="button" type="button" :disabled="busy" @click="creating=false">取消</button></div></form></el-dialog>
  </section>
</template>
<style scoped>
.project-overview{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin-bottom:30px}.overview-metric{display:flex;align-items:center;gap:16px;padding:20px;border:1px solid var(--wb-border);border-radius:var(--wb-radius);background:var(--wb-surface);box-shadow:var(--wb-shadow)}.metric-icon{display:grid;place-items:center;width:44px;height:44px;border-radius:11px;background:var(--wb-pale);color:var(--wb-primary);flex-shrink:0}.metric-icon.reports{background:#edf3ff;color:#3862a3}.metric-icon.running{background:#fff6e5;color:var(--wb-warning)}.overview-metric>div>span{display:block;font-size:12px;color:var(--wb-muted);margin-bottom:4px}.overview-metric strong{display:flex;align-items:baseline;gap:12px;font-family:Inter,system-ui,sans-serif;font-variant-numeric:tabular-nums;font-size:28px;font-weight:650;line-height:1.2}.overview-metric small{font-family:inherit;font-size:12px;font-weight:400;color:var(--wb-muted)}.project-list-toolbar{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:18px}.project-list-toolbar h2{margin:0}.project-list-toolbar p{margin:5px 0 0;font-size:12px;color:var(--wb-muted)}.count-label{display:inline-grid;place-items:center;min-width:24px;min-height:23px;padding:0 6px;border-radius:5px;background:#e6edf5;font-size:12px;color:var(--wb-muted);font-weight:550;margin-left:7px}.project-search{position:relative;display:flex;align-items:center;gap:8px;padding:0 11px;min-height:40px;border:1px solid var(--wb-border);border-radius:6px;background:var(--wb-surface);color:var(--wb-muted)}.project-search input{width:170px;min-width:0;padding:10px 0;border:0;outline:0;background:transparent;font-size:13px;color:var(--wb-ink)}.project-search:focus-within{outline:3px solid #0e877d;outline-offset:2px;border-color:var(--wb-primary)}.project-search input:focus-visible{outline:0}.icon-button{width:40px;padding:8px}.project-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,310px),1fr));gap:18px}.project-card{padding:22px;border:1px solid var(--wb-border);border-radius:var(--wb-radius);background:var(--wb-surface);box-shadow:var(--wb-shadow);transition:border-color .16s,box-shadow .16s}.project-card:hover{border-color:#a2bacb;box-shadow:0 5px 18px #172b4308}.project-card.current-project{border-color:#97c7c0}.project-card-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.project-symbol{width:46px;height:46px;background:#f0f5f8;color:#3c627c;border:1px solid #e0e8f0;border-radius:11px;display:grid;place-items:center}.project-title{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.project-card h3{font-size:19px;margin:0}.current-project-label{font-size:12px;color:var(--wb-primary);font-weight:550}.project-description{min-height:43px;font-size:13px;color:var(--wb-muted);line-height:1.7;margin:10px 0 18px}.project-card-meta{display:flex;justify-content:space-between;gap:12px;font-size:12px;color:var(--wb-muted);margin:12px 0}.project-card-meta>span:first-child{display:flex;align-items:center;gap:6px;white-space:nowrap}.project-card-meta>span:last-child{text-align:right;overflow-wrap:anywhere}.project-card-actions{display:flex;gap:8px;margin-top:19px;padding-top:18px;border-top:1px solid var(--wb-divider);flex-wrap:wrap}.project-file-details{border-top:1px solid var(--wb-divider);margin-top:16px;padding-top:12px}.project-file-details summary{min-height:30px;display:flex;justify-content:space-between;align-items:center;font-size:12px;color:var(--wb-muted);cursor:pointer;list-style:none}.project-file-details summary::-webkit-details-marker{display:none}.project-file-details[open] summary .app-icon{transform:rotate(180deg)}.project-file-details dl{font-size:12px;line-height:1.65;margin:12px 0 0}.project-file-details dt{color:var(--wb-muted)}.project-file-details dd{margin:4px 0 12px;overflow-wrap:anywhere}.workflow-guide{margin-top:30px;padding:22px;border:1px solid var(--wb-border);border-radius:var(--wb-radius);background:#eef3f8}.workflow-guide-heading{display:flex;align-items:center;gap:9px;color:#3b526a;font-size:13px;margin-bottom:20px}.workflow-guide-heading strong{font-weight:550}.workflow-strip{display:flex;align-items:center;justify-content:space-between;gap:20px}.workflow-strip>div{display:grid;grid-template-columns:28px 1fr;gap:5px 10px}.workflow-strip>div>span{grid-row:1/3;font-family:ui-monospace,monospace;font-size:12px;color:var(--wb-muted);margin-top:3px}.workflow-strip strong{font-size:13px;font-weight:600}.workflow-strip small{color:var(--wb-muted);font-size:12px}.workflow-strip>.app-icon{color:var(--wb-muted)}.workflow-guide>.button{margin:14px 0 -4px;padding-left:0}@media(max-width:1100px){.overview-metric{padding:16px;gap:12px}.overview-metric strong{display:block}.overview-metric small{display:block;margin-top:5px}.metric-icon{width:38px;height:38px}.project-list-toolbar{align-items:flex-start}}@media(max-width:760px){.project-file-details summary{min-height:44px}.project-overview{gap:8px;margin-bottom:24px}.overview-metric{padding:14px 10px;display:block}.metric-icon{width:30px;height:30px;border-radius:7px;margin-bottom:12px}.metric-icon .app-icon{width:17px;height:17px}.overview-metric strong{font-size:25px}.overview-metric small{font-size:12px;line-height:1.5}.overview-metric>div>span{font-size:12px}.project-list-toolbar{flex-direction:column;align-items:stretch;gap:14px}.project-list-toolbar>.actions{flex-wrap:nowrap}.project-search{flex:1;min-width:0;min-height:44px}.project-search input{width:100%;font-size:16px}.project-card{padding:20px}.project-description{min-height:0}.workflow-guide{padding:18px}.workflow-strip{flex-direction:column;align-items:stretch;gap:18px}.workflow-strip>.app-icon{display:none}.project-card-meta{gap:8px}}
</style>
